import{_ as a,o,c as s,a2 as t}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"About Memoh","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1788855895000}'),r={name:"about.md"};function n(i,e,l,h,c,d){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="about-memoh" tabindex="-1">About Memoh <a class="header-anchor" href="#about-memoh" aria-label="Permalink to &quot;About Memoh&quot;">​</a></h1><p>Memoh v0.13 is the open-source multi-agent platform. It lets you run multiple AI agents on one machine, with each agent getting its own workspace, browser, network, tools, and long-term memory.</p><p>Agents can talk through Telegram, Discord, Lark, WeChat, Web UI, Email, and other channels. They can remember context, operate a browser or desktop, call MCP tools, install skills and connectors, run scheduled tasks, and enforce per-bot access rules.</p><p>The hosted Memoh SaaS service is coming soon. Join the <a href="https://memoh.ai/waitlist" target="_blank" rel="noreferrer">SaaS waitlist</a> if you want a managed option instead of operating your own deployment.</p><h2 id="distribution-modes" tabindex="-1">Distribution Modes <a class="header-anchor" href="#distribution-modes" aria-label="Permalink to &quot;Distribution Modes&quot;">​</a></h2><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Desktop is the native client for Memoh Cloud or a self-hosted server. It wraps the Web UI in a native window with a system tray and shortcuts, and can register the computer it runs on as a Computer that bots may use. It does not run a local server.</p><h3 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h3><p>Server Deploy is for always-on shared usage. Use it when Memoh should serve multiple users, keep channels online while your computer is offline, or run as a self-hosted service. The Docker Compose stack includes the backend, Web UI, database, memory services, and workspace runtime.</p><h2 id="what-v0-13-emphasizes" tabindex="-1">What v0.13 Emphasizes <a class="header-anchor" href="#what-v0-13-emphasizes" aria-label="Permalink to &quot;What v0.13 Emphasizes&quot;">​</a></h2><h3 id="agent-workspaces" tabindex="-1">Agent Workspaces <a class="header-anchor" href="#agent-workspaces" aria-label="Permalink to &quot;Agent Workspaces&quot;">​</a></h3><p>Each bot can use an isolated container workspace with files, commands, MCP hosting, network access, a headed browser, and a graphical desktop. Local and desktop setups can also use trusted local workspaces when host-level access is intentional.</p><h3 id="web-product" tabindex="-1">Web Product <a class="header-anchor" href="#web-product" aria-label="Permalink to &quot;Web Product&quot;">​</a></h3><p>The Web UI now covers more of the daily product surface: bot setup, sessions, providers, channels, workspace files, terminal and display panes, Supermarket, hooks, schedules, access control, and user preferences. v0.13 also includes English, Simplified Chinese, and Japanese UI language support.</p><h3 id="hooks-schedules-and-automation" tabindex="-1">Hooks, Schedules, And Automation <a class="header-anchor" href="#hooks-schedules-and-automation" aria-label="Permalink to &quot;Hooks, Schedules, And Automation&quot;">​</a></h3><p>Hooks let bots run small automation rules around supported events, while Schedule keeps recurring work moving without an active chat. Skills and connectors from the Supermarket extend what a bot can do without custom code.</p><h3 id="access-control" tabindex="-1">Access Control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access Control&quot;">​</a></h3><p>Access control is split between channel-side chat permissions and workspace-side user permissions. Bot owners can allow or block channel members, grant registered users workspace roles, and keep advanced ACL rules for cases that need more precise matching.</p><h2 id="where-to-start" tabindex="-1">Where To Start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where To Start&quot;">​</a></h2><ul><li><strong><a href="/guides/bot.html">Bot Setup</a></strong> - create and configure a bot.</li><li><strong><a href="/integrations/providers/llm.html">Providers And Models</a></strong> - configure model access.</li><li><strong><a href="/integrations/channels/">Channels</a></strong> - choose where bots are reachable.</li><li><strong><a href="/guides/skills.html">Skills</a></strong> and <strong><a href="/guides/supermarket.html">Supermarket</a></strong> - install reusable capabilities.</li><li><strong><a href="/guides/schedule.html">Scheduled Tasks</a></strong> and <strong><a href="/guides/access.html">Access Control</a></strong> - operate recurring work and permissions.</li><li><strong><a href="/self-hosted/">Self-hosted</a></strong> - deploy and maintain your own Memoh instance.</li></ul>',20)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
